def article(topic):
    slug, title, focus, thesis, fields, boundary = topic
    public_title = f'{focus.title()}: {title}'
    sections = [
        (f'Why {focus} matters', f'{thesis.capitalize()}. In daily article creation for virtual assistant services, a small ambiguity at intake can become a weak outline, a stalled review, or a public statement that nobody can confidently support. Start by naming the reader and the decision the article should help them make. Do not treat activity as evidence that the question is ready.'),
        ('Define the record before work begins', f'Create one record for the article question and capture {fields}. Keep unknown values visible as questions rather than filling gaps with plausible language. A record is useful when a person who did not attend the original conversation can understand what is being attempted, what is deliberately excluded, and what decision is waiting.'),
        ('Use a concrete operating scenario', f'Test the record against a realistic virtual assistant services scenario: an operator is keeping article work moving while an editor remains accountable for public wording. Ask whether the workflow identifies the next action, the evidence needed, and the point where work must pause. If the scenario exposes a missing field, narrow the work or escalate it; do not hide the gap inside more prose.'),
        ('Keep preparation separate from judgment', f'{boundary} That boundary should appear beside the task, not only in a private understanding. An assistant may collect sources, compare versions, organize questions, check links, and maintain a queue. Those actions reduce friction. They do not make the assistant the authority for a claim, a sensitive exception, positioning, or release.'),
        ('Measure decision usefulness', f'Use a small defined sample and record required-field coverage, correction reason, unresolved-item age, appropriate escalation, and owner review effort. Label the sample and period. A local measure describes the chosen workflow under stated conditions; it does not prove a universal performance result or certify a provider.'),
        ('Design the handoff for recovery', f'Include the current version, completed checks, open questions, source or evidence links, proposed next step, and named owner. Use precise statuses such as waiting for source review or ready for editorial judgment. If the work changes, record the new question and reopen affected checks rather than silently carrying old assumptions forward.'),
        ('Review public boundaries', f'Before release, check for unsupported company facts, invented outcomes, testimonials, pricing claims, unnecessary personal information, and wording that sounds more certain than the evidence allows. Hypothetical examples should be labeled as examples. Recommendations should stay conditional where context matters. A control improves review visibility; it does not guarantee every article is correct.'),
        ('Set a reopening trigger', f'Close with a concrete trigger: a source change, a reader question, a broken destination, a changed brief, an unresolved approval condition, or a repeated correction. The trigger turns a one-time record into a maintainable routine. Virtual assistant services can keep evidence organized and route uncertainty while the editor, writer, or owner retains the consequential decision.'),
    ]
    out = ['---', f'slug: {slug}', f'title: {public_title}', f'excerpt: Practical guidance for {focus} in virtual assistant services article operations.', f'publishedAt: {DATE}', f'updatedAt: {DATE}', 'category: Operations', 'tags: [virtual assistant, article creation, editorial operations]', 'featuredImage: /blog/images/virtual-assistant-content-brief-quality.webp', f'heroImageAlt: {public_title}', 'readingTime: 10 minutes', 'relatedArticles: [virtual-assistant-content-calendar-operations, virtual-assistant-provider-vetting-checklist, virtual-assistant-outsourcing-readiness-checklist]', '---', f'# {public_title}', '', f'{thesis.capitalize()} This guide keeps virtual assistant services central while preserving the editor’s responsibility for the public answer.']
    for heading, body in sections:
        out += ['', f'## {heading}', '', body, '', f'For {focus}, ask what a reviewer would need to verify next. Preserve the source, version, date, and limitation beside the item. When the evidence is incomplete, state the missing decision plainly and route it to the accountable owner.']
    out += ['', '## Questions to ask before release', '', 'Can the next reviewer identify the reader, evidence boundary, current owner, and next decision? If not, pause the handoff. Use the [services library](/services) for adjacent support lanes and the [provider vetting guide](/provider-vetting) when defining supervision and backup questions. For a general control reference, consult the [NIST small business cybersecurity guidance](https://www.nist.gov/itl/smallbusinesscyber).', '', '### What if the request changes?', '', 'Record the changed question and reopen the affected checks. Do not silently carry an old thesis or approval into a materially different article.', '', '### Who makes the final decision?', '', 'The accountable editor or service owner decides public wording and release. A virtual assistant prepares evidence, maintains the record, and escalates uncertainty within the agreed role boundary.']
    return '\n'.join(out) + '\n'

entries = []
for old_path in BLOG.glob('virtual-assistant-aug18-*.mdx'):
    old_path.unlink()
for n, topic in enumerate(TOPICS, 1):
    slug = f'virtual-assistant-aug18-r5-{n:02d}-{topic[0].removeprefix("virtual-assistant-")}'
    path = BLOG / f'{slug}.mdx'
    path.write_text(article(topic).replace(f'slug: {topic[0]}', f'slug: {slug}', 1), encoding='utf-8')
    entries.append({'slug': slug, 'route': f'/blog/{slug}', 'sourcePath': f'content/blog/{slug}.mdx', 'sourceDateField': 'publishedAt', 'sourceDate': DATE, 'renderedDate': DATE, 'renderedDateFields': ['datePublished', 'time[datetime]'], 'provenance': 'strict-aug18-replacement', 'introducedByCommit': 'PENDING'})
manifest = ROOT / '.paperclip/aug18-2026/blog.json'
manifest.write_text(json.dumps({'schemaVersion': 1, 'contract': 'fleet-aug18-blog-replacement-v2', 'family': 'blog', 'targetDate': DATE, 'minimum': 22, 'entries': entries}, indent=2) + '\n', encoding='utf-8')
print(f'created {len(entries)} replacement articles; shortest body {min(len((BLOG / (e["slug"] + ".mdx")).read_text().split()) for e in entries)} words')
